import { fpcEndpoint } from './endpoint';
import type { PlanVoucherFilterDto, PlanVoucherListPageDto } from './types';

/**
 * FPC API facade — mirror `fpcEndpoint` (spread) so new endpoint methods
 * are always available on `fpcService` without manual re-wire drift.
 */
export const fpcService = {
  ...fpcEndpoint,

  // PlanVoucher — typed page wrapper (list returns PlanVoucherListPageDto)
  getPlanVoucherList: (
    params?: PlanVoucherFilterDto,
  ): Promise<PlanVoucherListPageDto> => fpcEndpoint.getPlanVoucherList(params),
};
